import itertools
import random

def check_clique(G, k):
    """Check if graph G has a clique of size k"""
    vertices = list(range(14))
    for combo in itertools.combinations(vertices, k):
        ok = True
        for i in range(k):
            for j in range(i+1, k):
                if combo[j] not in G[combo[i]]:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            return True, combo
    return False, None

def check_chromatic_number(G, max_colors):
    """Check if graph G can be colored with max_colors colors"""
    # Simple backtracking
    n = 14
    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        used = [False] * max_colors
        for u in G[v]:
            if colors[u] != -1:
                used[colors[u]] = True
        for c in range(max_colors):
            if not used[c]:
                colors[v] = c
                if backtrack(v+1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

def check_degrees(G, min_deg):
    for v in range(14):
        if len(G[v]) < min_deg:
            return False
    return True

def edges_from_adj(G):
    edges = []
    for u in range(14):
        for v in G[u]:
            if u < v:
                edges.append((u, v))
    return edges

def random_search(iterations=100000):
    for it in range(iterations):
        # Start with empty graph
        G = [set() for _ in range(14)]

        # Add edges to ensure min degree 5
        for v in range(14):
            needed = 5 - len(G[v])
            if needed > 0:
                candidates = [u for u in range(14) if u != v and u not in G[v]]
                random.shuffle(candidates)
                for u in candidates[:needed]:
                    G[v].add(u)
                    G[u].add(v)

        # Add some more random edges
        for _ in range(random.randint(0, 30)):
            u = random.randint(0, 13)
            v = random.randint(0, 13)
            if u != v and v not in G[u]:
                G[u].add(v)
                G[v].add(u)

        # Check constraints
        if not check_degrees(G, 5):
            continue

        has_k4, _ = check_clique(G, 4)
        if has_k4:
            continue

        if check_chromatic_number(G, 5):
            edges = edges_from_adj(G)
            return G, edges

    return None, None

