import itertools
def max_clique_size(G):
    for k in range(14, 2, -1):
        for combo in itertools.combinations(range(14), k):
            ok = True
            for i in range(k):
                for j in range(i+1, k):
                    if combo[j] not in G[combo[i]]:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                return k, combo
    return 0, None

