def chromatic_number(G):
    n = 14
    for max_colors in range(1, 15):
        colors = [-1] * n
        def backtrack(v):
            if v == n:
                return True
            used = [False] * max_colors
            for u in G[v]:
                if colors[u] != -1:
                    used[colors[u]] = True
            for c in range(max_colors):
                if not used[c]:
                    colors[v] = c
                    if backtrack(v+1):
                        return True
                    colors[v] = -1
            return False
        if backtrack(0):
            return max_colors
    return None

